package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.behavior.*; import com.wizzadrds.theworldremembers.inventory.*; import com.wizzadrds.theworldremembers.stress.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes; import net.minecraft.world.entity.EquipmentSlot; import net.minecraft.world.item.ItemStack; import net.minecraft.world.item.Items;
public final class Phase4BehaviorGameTests {
 @GameTest public void persistentBehaviorStateCreated(GameTestHelper c){var v=c.spawn(EntityTypes.VILLAGER,2,1,2);c.runAtTickTime(1,()->{TheWorldRemembers.processWorld(c.getLevel());var s=NpcBehaviorManager.get(c.getLevel()).get(v.getUUID());if(s==null){c.fail("No persistent behavior state");return;}c.succeed();});}
 @GameTest public void equipmentMirrorsRealMainHand(GameTestHelper c){var v=c.spawn(EntityTypes.VILLAGER,2,1,2);v.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.EMERALD));c.runAtTickTime(1,()->{TheWorldRemembers.processWorld(c.getLevel());var s=NpcEquipmentManager.get(c.getLevel()).get(v.getUUID());if(s==null||!s.mainHand().equals("minecraft:emerald")){c.fail("Equipment state is not synchronized");return;}c.succeed();});}
 @GameTest public void criticalStressUsesReturnHomeIntent(GameTestHelper c){var v=c.spawn(EntityTypes.VILLAGER,2,1,2);var stress=NpcStressManager.get(c.getLevel());stress.increase(v.getUUID(),100);c.runAtTickTime(1,()->{TheWorldRemembers.processWorld(c.getLevel());var s=NpcBehaviorManager.get(c.getLevel()).get(v.getUUID());if(s==null||s.priority()<90){c.fail("Critical stress did not create high-priority safety behavior");return;}c.succeed();});}
}
